package ru.assistant.mail;

import com.jacob.activeX.ActiveXComponent;
import com.jacob.com.ComFailException;
import com.jacob.com.Dispatch;
import com.jacob.com.Variant;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.ArrayList;
import java.util.List;

/**
 * Bridges to a locally running Outlook desktop client via JACOB/COM.
 * Not unit-testable: requires a real Outlook installation + native jacob DLL
 * on the PATH, neither of which is available on this development machine.
 * The contract is exercised through {@link MockMailChannel} instead; this
 * class is verified manually on the exam machine (see README).
 */
public class OutlookMailChannel implements MailChannel {

    private static final Logger log = LoggerFactory.getLogger(OutlookMailChannel.class);

    private static final int OL_FOLDER_INBOX = 6;

    private final String folderName;

    public OutlookMailChannel(String folderName) {
        this.folderName = folderName;
    }

    @Override
    public List<Msg> fetchUnread() throws MailChannelException {
        ActiveXComponent outlookApp = null;
        try {
            outlookApp = new ActiveXComponent("Outlook.Application");
            Dispatch namespace = Dispatch.call(outlookApp, "GetNamespace", "MAPI").toDispatch();
            Dispatch folder = resolveFolder(namespace);
            Dispatch items = Dispatch.get(folder, "Items").toDispatch();
            Dispatch unreadItems = Dispatch.call(items, "Restrict", "[Unread] = true").toDispatch();

            List<Msg> result = new ArrayList<>();
            int count = Dispatch.get(unreadItems, "Count").getInt();
            for (int i = 1; i <= count; i++) {
                Dispatch mailItem = Dispatch.call(unreadItems, "Item", i).toDispatch();
                result.add(toMsg(mailItem));
            }
            return result;
        } catch (ComFailException e) {
            throw new MailChannelException("Failed to fetch unread messages from Outlook", e);
        } finally {
            if (outlookApp != null) {
                outlookApp.safeRelease();
            }
        }
    }

    @Override
    public void reply(Msg original, String body) throws MailChannelException {
        ActiveXComponent outlookApp = null;
        try {
            outlookApp = new ActiveXComponent("Outlook.Application");
            Dispatch namespace = Dispatch.call(outlookApp, "GetNamespace", "MAPI").toDispatch();
            Dispatch folder = resolveFolder(namespace);
            Dispatch mailItem = findByEntryId(folder, original.getId());
            if (mailItem == null) {
                throw new MailChannelException("Original message not found in Outlook folder, id masked");
            }
            Dispatch replyItem = Dispatch.call(mailItem, "Reply").toDispatch();
            Dispatch.put(replyItem, "Body", body);
            Dispatch.call(replyItem, "Send");
        } catch (ComFailException e) {
            throw new MailChannelException("Failed to send reply via Outlook", e);
        } finally {
            if (outlookApp != null) {
                outlookApp.safeRelease();
            }
        }
    }

    private Dispatch resolveFolder(Dispatch namespace) {
        if (folderName == null || folderName.isEmpty() || "Inbox".equalsIgnoreCase(folderName)) {
            return Dispatch.call(namespace, "GetDefaultFolder", OL_FOLDER_INBOX).toDispatch();
        }
        Dispatch inbox = Dispatch.call(namespace, "GetDefaultFolder", OL_FOLDER_INBOX).toDispatch();
        Dispatch folders = Dispatch.get(inbox, "Folders").toDispatch();
        return Dispatch.call(folders, "Item", folderName).toDispatch();
    }

    private Dispatch findByEntryId(Dispatch folder, String entryId) {
        Dispatch items = Dispatch.get(folder, "Items").toDispatch();
        int count = Dispatch.get(items, "Count").getInt();
        for (int i = 1; i <= count; i++) {
            Dispatch candidate = Dispatch.call(items, "Item", i).toDispatch();
            String candidateId = Dispatch.get(candidate, "EntryID").getString();
            if (entryId.equals(candidateId)) {
                return candidate;
            }
        }
        return null;
    }

    private Msg toMsg(Dispatch mailItem) {
        String id = Dispatch.get(mailItem, "EntryID").getString();
        String from = getStringSafe(mailItem, "SenderEmailAddress");
        String subject = getStringSafe(mailItem, "Subject");
        String body = getStringSafe(mailItem, "Body");
        String receivedAtIso = getReceivedIso(mailItem);
        return new Msg(id, from, subject, body, receivedAtIso);
    }

    private String getStringSafe(Dispatch item, String property) {
        try {
            Variant value = Dispatch.get(item, property);
            return value == null ? "" : value.getString();
        } catch (ComFailException e) {
            log.warn("Failed to read Outlook property {}, defaulting to empty string", property);
            return "";
        }
    }

    private String getReceivedIso(Dispatch mailItem) {
        try {
            Variant received = Dispatch.get(mailItem, "ReceivedTime");
            return received.getJavaObject().toString();
        } catch (ComFailException | RuntimeException e) {
            log.warn("Failed to read Outlook ReceivedTime, defaulting to empty string");
            return "";
        }
    }
}

package ru.assistant.llm;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class HttpLlmClient implements LlmClient {

    private static final MediaType JSON_MEDIA_TYPE = MediaType.parse("application/json; charset=utf-8");
    private static final int MAX_ATTEMPTS = 2;

    private final OkHttpClient httpClient;
    private final String endpoint;
    private final String model;
    private final String apiKey;
    private final ObjectMapper objectMapper;

    public HttpLlmClient(OkHttpClient httpClient, String endpoint, String model, String apiKey, long timeoutMs) {
        this.httpClient = httpClient.newBuilder()
                .callTimeout(timeoutMs, TimeUnit.MILLISECONDS)
                .build();
        this.endpoint = endpoint;
        this.model = model;
        this.apiKey = apiKey;
        this.objectMapper = new ObjectMapper();
    }

    @Override
    public ChatResponse chat(List<ChatMessage> messages, List<ToolSpec> tools) throws LlmException {
        Request request;
        try {
            request = buildRequest(messages, tools);
        } catch (IOException e) {
            throw new LlmException("Failed to build LLM request payload", e);
        }

        Response response = null;
        IOException lastNetworkError = null;

        for (int attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
            if (response != null) {
                response.close();
                response = null;
            }
            try {
                response = httpClient.newCall(request).execute();
                lastNetworkError = null;
            } catch (IOException e) {
                lastNetworkError = e;
                if (attempt == MAX_ATTEMPTS) {
                    throw new LlmException("LLM request failed: network/timeout error, host=" + safeHost(request), e);
                }
                continue;
            }
            if (isServerError(response.code()) && attempt < MAX_ATTEMPTS) {
                continue;
            }
            break;
        }

        try {
            if (response == null) {
                throw new LlmException("LLM request failed: no response received, host=" + safeHost(request), lastNetworkError);
            }
            if (!response.isSuccessful()) {
                throw new LlmException("LLM request failed: status=" + response.code() + ", host=" + safeHost(request));
            }
            String bodyString;
            try {
                ResponseBody responseBody = response.body();
                bodyString = responseBody != null ? responseBody.string() : "";
            } catch (IOException e) {
                throw new LlmException("Failed to read LLM response body, host=" + safeHost(request), e);
            }
            try {
                return parseResponse(bodyString);
            } catch (IOException | RuntimeException e) {
                throw new LlmException("Failed to parse LLM response, host=" + safeHost(request), e);
            }
        } finally {
            if (response != null) {
                response.close();
            }
        }
    }

    private boolean isServerError(int code) {
        return code / 100 == 5;
    }

    private String safeHost(Request request) {
        return request.url().host();
    }

    private Request buildRequest(List<ChatMessage> messages, List<ToolSpec> tools) throws IOException {
        ObjectNode root = objectMapper.createObjectNode();
        root.put("model", model);

        ArrayNode messagesNode = root.putArray("messages");
        for (ChatMessage message : messages) {
            ObjectNode messageNode = messagesNode.addObject();
            messageNode.put("role", message.getRole());
            if (message.getContent() != null) {
                messageNode.put("content", message.getContent());
            } else {
                messageNode.putNull("content");
            }
            if ("tool".equals(message.getRole()) && message.getToolCallId() != null) {
                messageNode.put("tool_call_id", message.getToolCallId());
            }
        }

        if (tools != null && !tools.isEmpty()) {
            ArrayNode toolsNode = root.putArray("tools");
            for (ToolSpec tool : tools) {
                ObjectNode toolNode = toolsNode.addObject();
                toolNode.put("type", "function");
                ObjectNode functionNode = toolNode.putObject("function");
                functionNode.put("name", tool.getName());
                functionNode.put("description", tool.getDescription());
                JsonNode parametersNode = objectMapper.readTree(tool.getJsonSchema());
                functionNode.set("parameters", parametersNode);
            }
        }

        String json = objectMapper.writeValueAsString(root);
        RequestBody body = RequestBody.create(json, JSON_MEDIA_TYPE);

        return new Request.Builder()
                .url(endpoint)
                .header("Authorization", "Bearer " + apiKey)
                .post(body)
                .build();
    }

    private ChatResponse parseResponse(String responseBody) throws IOException {
        JsonNode root = objectMapper.readTree(responseBody);
        JsonNode choices = root.path("choices");
        JsonNode choice = choices.isArray() && choices.size() > 0 ? choices.get(0) : objectMapper.createObjectNode();
        JsonNode message = choice.path("message");

        String content = null;
        JsonNode contentNode = message.path("content");
        if (!contentNode.isMissingNode() && !contentNode.isNull()) {
            content = contentNode.asText();
        }

        List<ToolCall> toolCalls = new ArrayList<>();
        JsonNode toolCallsNode = message.path("tool_calls");
        if (toolCallsNode.isArray()) {
            for (JsonNode toolCallNode : toolCallsNode) {
                String id = toolCallNode.path("id").asText(null);
                JsonNode function = toolCallNode.path("function");
                String name = function.path("name").asText(null);
                String argumentsJson = function.path("arguments").asText(null);
                toolCalls.add(new ToolCall(id, name, argumentsJson));
            }
        }

        JsonNode finishReasonNode = choice.path("finish_reason");
        String finishReason = (finishReasonNode.isMissingNode() || finishReasonNode.isNull())
                ? null
                : finishReasonNode.asText();

        return new ChatResponse(content, toolCalls, finishReason);
    }
}

package ru.assistant.llm;

import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class HttpLlmClientTest {

    private MockWebServer server;
    private OkHttpClient httpClient;

    @Before
    public void setUp() throws IOException {
        server = new MockWebServer();
        server.start();
        httpClient = new OkHttpClient();
    }

    @After
    public void tearDown() throws IOException {
        server.shutdown();
    }

    private HttpLlmClient newClient() {
        String endpoint = server.url("/v1/chat/completions").toString();
        return new HttpLlmClient(httpClient, endpoint, "test-model", "test-api-key", 5000L);
    }

    private List<ChatMessage> sampleMessages() {
        return Collections.singletonList(ChatMessage.user("What's the weather in Moscow?"));
    }

    @Test
    public void parsesSuccessfulResponseWithToolCalls() throws Exception {
        String body = "{"
                + "\"choices\":[{"
                + "\"message\":{"
                + "\"content\":null,"
                + "\"tool_calls\":[{"
                + "\"id\":\"call_1\","
                + "\"type\":\"function\","
                + "\"function\":{\"name\":\"get_weather\",\"arguments\":\"{\\\"city\\\":\\\"Moscow\\\"}\"}"
                + "}]"
                + "},"
                + "\"finish_reason\":\"tool_calls\""
                + "}]"
                + "}";
        server.enqueue(new MockResponse().setResponseCode(200).setBody(body));

        HttpLlmClient client = newClient();
        ChatResponse response = client.chat(sampleMessages(), Collections.<ToolSpec>emptyList());

        assertNull(response.getContent());
        assertEquals("tool_calls", response.getFinishReason());
        assertEquals(1, response.getToolCalls().size());
        ToolCall call = response.getToolCalls().get(0);
        assertEquals("call_1", call.getId());
        assertEquals("get_weather", call.getName());
        assertEquals("{\"city\":\"Moscow\"}", call.getArgumentsJson());

        assertEquals(1, server.getRequestCount());
        RecordedRequest recorded = server.takeRequest();
        assertEquals("Bearer test-api-key", recorded.getHeader("Authorization"));
        assertTrue(recorded.getBody().readUtf8().contains("\"model\":\"test-model\""));
    }

    @Test
    public void retriesOnceAfterServerErrorThenSucceeds() throws Exception {
        String successBody = "{\"choices\":[{\"message\":{\"content\":\"hello there\"},\"finish_reason\":\"stop\"}]}";
        server.enqueue(new MockResponse().setResponseCode(500).setBody("internal error"));
        server.enqueue(new MockResponse().setResponseCode(200).setBody(successBody));

        HttpLlmClient client = newClient();
        ChatResponse response = client.chat(sampleMessages(), Collections.<ToolSpec>emptyList());

        assertEquals("hello there", response.getContent());
        assertEquals("stop", response.getFinishReason());
        assertTrue(response.getToolCalls().isEmpty());
        assertEquals(2, server.getRequestCount());
    }

    @Test
    public void failsAfterSingleRetryOnRepeatedServerErrors() throws Exception {
        server.enqueue(new MockResponse().setResponseCode(500).setBody("internal error 1"));
        server.enqueue(new MockResponse().setResponseCode(500).setBody("internal error 2"));

        HttpLlmClient client = newClient();
        try {
            client.chat(sampleMessages(), Collections.<ToolSpec>emptyList());
            fail("Expected LlmException after repeated server errors");
        } catch (LlmException e) {
            assertTrue(e.getMessage().contains("500"));
        }

        assertEquals(2, server.getRequestCount());
    }
}

package ru.assistant.llm;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;

public class MockLlmClient implements LlmClient {

    private final Deque<ChatResponse> queue;
    private LlmException pendingException;

    public MockLlmClient(List<ChatResponse> responses) {
        this.queue = new ArrayDeque<>(responses);
    }

    public void throwOnNextCall(LlmException toThrow) {
        this.pendingException = toThrow;
    }

    @Override
    public ChatResponse chat(List<ChatMessage> messages, List<ToolSpec> tools) throws LlmException {
        if (pendingException != null) {
            LlmException toThrow = pendingException;
            pendingException = null;
            throw toThrow;
        }
        if (queue.isEmpty()) {
            throw new LlmException("MockLlmClient: response queue is empty (test misconfiguration) - "
                    + "configure enough queued ChatResponse entries for the expected number of chat() calls");
        }
        return queue.poll();
    }
}

package ru.assistant.llm;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class MockLlmClientTest {

    private List<ChatMessage> anyMessages() {
        return Collections.singletonList(ChatMessage.user("hello"));
    }

    private List<ToolSpec> noTools() {
        return Collections.emptyList();
    }

    @Test
    public void returnsQueuedResponsesInOrder() throws Exception {
        ChatResponse first = new ChatResponse("first", Collections.<ToolCall>emptyList(), "stop");
        ChatResponse second = new ChatResponse("second", Collections.<ToolCall>emptyList(), "stop");
        MockLlmClient client = new MockLlmClient(Arrays.asList(first, second));

        ChatResponse actualFirst = client.chat(anyMessages(), noTools());
        ChatResponse actualSecond = client.chat(anyMessages(), noTools());

        assertEquals("first", actualFirst.getContent());
        assertEquals("second", actualSecond.getContent());
    }

    @Test
    public void emptyQueueThrowsLlmExceptionNotNpe() {
        MockLlmClient client = new MockLlmClient(Collections.<ChatResponse>emptyList());

        try {
            client.chat(anyMessages(), noTools());
            fail("Expected LlmException");
        } catch (LlmException e) {
            assertTrue(e.getMessage().toLowerCase().contains("misconfiguration"));
        }
    }

    @Test
    public void throwOnNextCallThrowsOnceThenResumesNormalBehavior() throws Exception {
        ChatResponse queued = new ChatResponse("after-throw", Collections.<ToolCall>emptyList(), "stop");
        MockLlmClient client = new MockLlmClient(Arrays.asList(queued));
        LlmException scheduled = new LlmException("boom");
        client.throwOnNextCall(scheduled);

        try {
            client.chat(anyMessages(), noTools());
            fail("Expected scheduled LlmException on first call");
        } catch (LlmException e) {
            assertEquals(scheduled, e);
        }

        ChatResponse actual = client.chat(anyMessages(), noTools());
        assertEquals("after-throw", actual.getContent());
    }
}

